import workcell, re, sys, json
def loc():
    t = workcell.call("vision","locate").text
    d={}
    m=re.search(r"socket hole centre: x=([-\d.]+) y=([-\d.]+) mm, top at z=([-\d.]+)",t); d['hole']=tuple(map(float,m.groups()))
    m=re.search(r"peg: centre x=([-\d.]+) y=([-\d.]+) z=([-\d.]+) mm; lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+) mm; tilt ([-\d.]+)",t)
    if m:
        g=list(map(float,m.groups())); d['peg_c']=g[0:3]; d['peg_low']=g[3:6]; d['tilt']=g[6]
    return d
def tcp():
    t=workcell.call("robot","status").text
    m=re.search(r"right arm: TCP at x=([-\d.]+) y=([-\d.]+) z=([-\d.]+)",t); return list(map(float,m.groups()))
def step(dx,dy,dz):
    r=workcell.call("robot","step","right",str(dx),str(dy),str(dz)); print(r.text); return r
def align():
    d=loc(); p=tcp(); print(d,p)
    ex=d['hole'][0]-d['peg_low'][0]; ey=d['hole'][1]-d['peg_low'][1]
    print("err",ex,ey)
    return ex,ey,d,p
if __name__=="__main__":
    for i in range(3):
        ex,ey,d,p=align()
        if abs(ex)<0.7 and abs(ey)<0.7: break
        workcell.call("robot","move","right",str(p[0]+ex),str(p[1]+ey),str(p[2]))
EOF
